// This file helps TypeScript understand our custom path aliases
declare module "@/*" {
  const value: any;
  export default value;
}

declare module "@components/*" {
  const value: any;
  export default value;
}

declare module "@constants/*" {
  const value: any;
  export default value;
}

declare module "@store/*" {
  const value: any;
  export default value;
}

declare module "@types/*" {
  const value: any;
  export default value;
}

declare module "@utils/*" {
  const value: any;
  export default value;
}

declare module "@graphql/*" {
  const value: any;
  export default value;
}
